import asyncio
from playwright.async_api import async_playwright

dsl = """infographic chart-bar-plain-text
data
  title The World's Most Valuable Companies in 2025
  desc Extreme concentration at the top: NVIDIA leads at $4.82T. The top 10 hold ~$25.4T out of $142.9T total global value. U.S. dominates with 15 of the top 20 companies.
  values
    - label NVIDIA (US)
      value 4.82
    - label Alphabet (US)
      value 4.03
    - label Apple (US)
      value 3.87
    - label Microsoft (US)
      value 3.12
    - label Amazon (US)
      value 2.68
    - label Broadcom (US)
      value 1.89
    - label TSMC (Taiwan)
      value 1.88
    - label Saudi Aramco (SA)
      value 1.77
    - label Meta (US)
      value 1.71
    - label Tesla (US)
      value 1.46
theme
  palette #1e3a8a #1d4ed8 #2563eb #3b82f6 #60a5fa #93c5fd #bfdbfe #dbeafe #e0f2fe #f0f9ff
"""

html_content = f"""
<!DOCTYPE html>
<html>
<head>
<meta charset="utf-8">
<title>Poster - Infographic</title>
<style>
  body {{
    background: #0f172a;
    margin: 0;
    padding: 0;
    width: 1080px;
    height: 1920px;
    display: flex;
    justify-content: center;
    align-items: center;
  }}
  #container {{
    width: 960px;
    height: 1700px;
    filter: invert(1) hue-rotate(180deg);
  }}
</style>
</head>
<body>
<div id="container"></div>
<script src="/app/vendor/infographic.min.js"></script>
<script>
  try {{
    const infographic = new AntVInfographic.Infographic({{
      container: '#container',
      width: '100%',
      height: '100%',
    }});
    infographic.render(`{dsl}`);
    window.renderComplete = true;
  }} catch (e) {{
    console.error(e);
    window.renderError = e.message;
  }}
</script>
</body>
</html>
"""

async def main():
    with open('/app/poster.html', 'w', encoding='utf-8') as f:
        f.write(html_content)

    async with async_playwright() as p:
        browser = await p.chromium.launch(headless=True)
        page = await browser.new_page(viewport={"width": 1080, "height": 1920}, device_scale_factor=2)
        await page.goto("file:///app/poster.html")
        await page.wait_for_timeout(2000) # wait for fonts/rendering

        # Check if renderComplete is true
        is_complete = await page.evaluate("window.renderComplete")
        if not is_complete:
            err = await page.evaluate("window.renderError")
            print(f"Render failed: {err}")

        await page.screenshot(path='/app/output/final_poster.png')
        await browser.close()

if __name__ == '__main__':
    asyncio.run(main())
